    s=re.sub(r"\s*\(s\.\s?lat\.\)","",r["Species"]); s=re.sub(r"\s+(subsp|var)\.?\s+\S+","",s)
    sub=re.sub(r"^(subsp|var)\.?\s*","",r["subsp"])
    m=re.search(r"\s(subsp|var)\.?\s+(\S+)",r["Species"]); 
    if m and not sub: sub=m.group(2)
    return (r["Genus"],s.strip(),sub)
def nz(v): return re.sub(r"\s+","",v).replace("–","-")
for f in sorted({r["File_name"] for r in o}):
    A=defaultdict(Counter);B=defaultdict(Counter)
    for r in o:
        if r["File_name"]==f: A[sp(r)][tuple(nz(r[c]) for c in V)]+=1
    for r in s:
        if r["File_name"]==f: B[sp(r)][tuple(nz(r[c]) for c in V)]+=1
    taxa=set(A)|set(B); only_o=[t for t in taxa if t not in B]; only_s=[t for t in taxa if t not in A]
    diff=[t for t in taxa if t in A and t in B and A[t]!=B[t]]
    print(f"\n== {f}: taxa {len(A)} vs {len(B)} | opus-only taxa {len(only_o)} sonnet-only {len(only_s)} | taxa with value differences {len(diff)}")
    for t in (only_o[:3]): print("   O-only",t)
    for t in (only_s[:3]): print("   S-only",t)
    cc=Counter()
    for t in diff:
        a=A[t]-B[t]; b=B[t]-A[t]
        for x,y in zip(sorted(a.elements()),sorted(b.elements())):
            for i,c in enumerate(V):
                if x[i]!=y[i]: cc[c]+=1
    print("   column diffs (value-row level):",dict(cc))
    for t in diff[:4]:
        a=list((A[t]-B[t]).elements()); b=list((B[t]-A[t]).elements())
        def show(x): return {V[i]:x[i] for i in range(len(V)) if x[i]}
        print("   ",t,"\n      O:",[show(x) for x in a][:3],"\n      S:",[show(x) for x in b][:3])
